// Reuse only immutable actual-field fixtures; reference main is not invoked.
#define main rho_actual_reference_main_not_invoked
#include "test_rho_log_actual.cpp"
#undef main

struct SourceNoiseStats {size_t rows=0,zero_curvature_rows=0;Real max_h_noise=0,max_lapse_noise=0,max_m_noise=0,max_h_gain=0,max_lapse_gain=0,max_unitA_m_gain=0,max_chi_hessian_proxy=0,max_alpha_chi_hessian_proxy=0,max_physical_gradient_noise=0;long double weight=0,h2=0,l2=0;
  void Print()const{std::cout<<"{\"rows\":"<<rows<<",\"zero_actual_curvature_rows\":"<<zero_curvature_rows<<",\"maximum_H_noise\":"<<max_h_noise<<",\"maximum_principal_lapse_noise\":"<<max_lapse_noise<<",\"maximum_actual_momentum_noise\":"<<max_m_noise<<",\"maximum_H_source_l1\":"<<max_h_gain<<",\"maximum_principal_lapse_source_l1\":"<<max_lapse_gain<<",\"maximum_unitA_momentum_gain\":"<<max_unitA_m_gain<<",\"maximum_chi_over_h2_hessian_l1\":"<<max_chi_hessian_proxy<<",\"maximum_alpha_chi_over_h2_hessian_l1\":"<<max_alpha_chi_hessian_proxy<<",\"maximum_physical_chi_gradient_noise\":"<<max_physical_gradient_noise<<",\"physical_volume_H_noise_rms\":"<<std::sqrt(Real(h2/weight))<<",\"physical_volume_principal_lapse_noise_rms\":"<<std::sqrt(Real(l2/weight))<<'}';}
};
template<class Fit>void SourceNoise(const char *name,const Fit &fit,const h::PunctureLogPlans::Row &row,const Grid &grid,const std::vector<Datum> &initial,const V &stored,SourceNoiseStats &stats,bool strict_ready){
  const size_t p=row.active;const auto &x=grid.geometry[p].x;const Real dx=Spacing(grid,p),r=initial[p].r,chi=initial[p].chi,alpha=initial[p].alpha,omega=(1-r*r)/2,A0=(1+r*r)/2;V data[2],noisy[2];Real input_noise=0;
  for(size_t i=0;i<row.donors.size();++i)for(int f=0;f<2;++f){const Real value=stored[2*row.donors[i]+f],perturbed=value+1e-12*(f==0?(std::sin(1.7*i)+std::cos(.9*i))/2:(std::cos(1.31*i)-std::sin(.73*i))/2);data[f].push_back(value);noisy[f].push_back(perturbed);input_noise=std::max(input_noise,std::abs(perturbed-value));}
  const auto q=EvaluateActual(fit,data[0],stored[2*p],h::PuncturePosition{}),a=EvaluateActual(fit,data[1],stored[2*p+1],h::PuncturePosition{}),nq=EvaluateActual(fit,noisy[0],stored[2*p],h::PuncturePosition{}),na=EvaluateActual(fit,noisy[1],stored[2*p+1],h::PuncturePosition{});
  Real Hgain=0,Lgain=0,grad_l1[3]{},hess_l1[3][3]{},momentum_l1[3]{};
  for(size_t i=0;i<row.donors.size();++i){V unit(row.donors.size(),0);unit[i]=1;typename Fit::Result impulse;if(!fit.Evaluate(unit,h::PuncturePosition{},impulse))throw std::runtime_error("source impulse rejected");Real hc=0,lc_chi=0,lc_alpha=0;
    for(int j=0;j<3;++j){const Real d=impulse.gradient[j],dd=impulse.hessian[j][j],ag=a.d[j]+x[j]/A0;grad_l1[j]+=std::abs(d);for(int k=0;k<3;++k)hess_l1[j][k]+=std::abs(impulse.hessian[j][k]);
      hc+=chi*(2*omega*x[j]*d+omega*omega*(2*dd-q.d[j]*d));lc_chi+=.5*alpha*chi*ag*d;lc_alpha-=alpha*chi*(dd+(2*ag-.5*q.d[j])*d);}
    Hgain+=std::abs(hc);Lgain+=std::abs(lc_chi)+std::abs(lc_alpha);
    for(int k=0;k<3;++k){Real m=0;for(int j=0;j<3;++j){const Real tensor=1.5*initial[p].arr*(x[j]*x[k]/(r*r)-(j==k?1./3:0));m-=1.5*omega*tensor*impulse.gradient[j];}momentum_l1[k]+=std::abs(m);}
  }
  Real dh=0,dl=0,dm=0,delta_g2=0,max_raw_gradient_noise=0,G2=0,hessian_proxy=0;
  for(int j=0;j<3;++j){const Real dq=nq.d[j]-q.d[j],da=na.d[j]-a.d[j],dda=na.dd[j][j]-a.dd[j][j],ddq=nq.dd[j][j]-q.dd[j][j],ag=a.d[j]+x[j]/A0;
    dh+=chi*(2*omega*x[j]*dq+omega*omega*(2*ddq-q.d[j]*dq-.5*dq*dq));dl-=alpha*chi*(dda+2*ag*da+da*da-.5*(q.d[j]*da+dq*ag+dq*da));delta_g2+=dq*dq;max_raw_gradient_noise=std::max(max_raw_gradient_noise,std::abs(dq));G2+=grad_l1[j]*grad_l1[j];for(int k=0;k<3;++k)hessian_proxy=std::max(hessian_proxy,hess_l1[j][k]);}
  for(int k=0;k<3;++k){Real m=0;for(int j=0;j<3;++j){const Real tensor=1.5*initial[p].arr*(x[j]*x[k]/(r*r)-(j==k?1./3:0));m-=1.5*omega*tensor*(nq.d[j]-q.d[j]);}dm=std::max(dm,std::abs(m));}
  const Real Hbound=input_noise*Hgain+.5*chi*omega*omega*input_noise*input_noise*G2,Lbound=input_noise*Lgain+1.5*alpha*chi*input_noise*input_noise*G2;
  if(std::abs(dh)>Hbound+1e-12||std::abs(dl)>Lbound+1e-12)throw std::runtime_error("physical source perturbation exceeds functional bound");
  const Real unitA_gain=1.5*omega*std::sqrt(G2),w=grid.volumes[p]/std::pow(chi,1.5);++stats.rows;stats.zero_curvature_rows+=initial[p].arr==0;stats.weight+=w;stats.h2+=static_cast<long double>(w)*dh*dh;stats.l2+=static_cast<long double>(w)*dl*dl;
  stats.max_h_noise=std::max(stats.max_h_noise,std::abs(dh));stats.max_lapse_noise=std::max(stats.max_lapse_noise,std::abs(dl));stats.max_m_noise=std::max(stats.max_m_noise,dm);stats.max_h_gain=std::max(stats.max_h_gain,Hgain);stats.max_lapse_gain=std::max(stats.max_lapse_gain,Lgain);stats.max_unitA_m_gain=std::max(stats.max_unitA_m_gain,unitA_gain);stats.max_chi_hessian_proxy=std::max(stats.max_chi_hessian_proxy,chi*hessian_proxy);stats.max_alpha_chi_hessian_proxy=std::max(stats.max_alpha_chi_hessian_proxy,alpha*chi*hessian_proxy);stats.max_physical_gradient_noise=std::max(stats.max_physical_gradient_noise,chi*max_raw_gradient_noise);
  std::cout<<"{\"phase\":\"source_noise\",\"basis\":\""<<name<<"\",\"point\":"<<p<<",\"rho_over_h\":"<<r/dx<<",\"strict_rho_supported\":"<<strict_ready<<",\"chi\":"<<chi<<",\"alpha\":"<<alpha<<",\"chi_over_h2_hessian_l1\":"<<chi*hessian_proxy<<",\"alpha_chi_over_h2_hessian_l1\":"<<alpha*chi*hessian_proxy<<",\"H_source_l1\":"<<Hgain<<",\"principal_lapse_source_l1\":"<<Lgain<<",\"H_noise\":"<<dh<<",\"principal_lapse_noise\":"<<dl<<",\"actual_momentum_noise\":"<<dm<<",\"unitA_momentum_gain\":"<<unitA_gain<<",\"physical_chi_gradient_noise\":"<<chi*max_raw_gradient_noise<<",\"input_noise_max\":"<<input_noise<<"}\n";
}
int main(int argc,char **argv){Kokkos::initialize(argc,argv);int status=0;try{
  if(argc!=2)throw std::invalid_argument("usage actual initial.dat");auto grid=MakeGrid();const auto initial=ReadInitial(argv[1],grid);V stored(2*initial.size());for(size_t p=0;p<initial.size();++p){stored[2*p]=std::log(initial[p].chi);stored[2*p+1]=std::log(initial[p].alpha)-std::log(Chart(grid.geometry[p].x,1).reference.value);}h::PuncturePosition point;h::PunctureLogPlans base(grid,point);std::cout<<std::setprecision(17);SourceNoiseStats stats[3];size_t strict_rejected=0,raw_rejected=0,odd_rejected=0;
  for(const auto &row:base.rows){const auto &x=grid.geometry[row.active].x;std::vector<Single::Point> points;for(size_t donor:row.donors){const auto &d=grid.geometry[donor].x;points.push_back({d[0],d[1],d[2]});}Single raw;Single::Options options;options.maximum_gradient_l1=options.maximum_hessian_l1=1e9;const bool ready=raw.Build({x[0],x[1],x[2]},points,Spacing(grid,row.active),point,options);bool strict=false;
    if(ready){const auto &d=raw.diagnostics();strict=d.value_weight_l1<=16&&d.scaled_gradient_weight_l1<=32&&d.scaled_hessian_weight_l1<=64;strict_rejected+=!strict;SourceNoise("rho_raw",raw,row,grid,initial,stored,stats[1],strict);}else{++raw_rejected;std::cout<<"{\"phase\":\"unsupported\",\"basis\":\"rho_raw\",\"point\":"<<row.active<<",\"status\":\""<<raw.diagnostics().status<<"\"}\n";}
    SourceNoise("base",row.plan,row,grid,initial,stored,stats[0],strict);Odd odd;if(odd.Build({x[0],x[1],x[2]},points,Spacing(grid,row.active),point))SourceNoise("fullodd",odd,row,grid,initial,stored,stats[2],strict);else{++odd_rejected;std::cout<<"{\"phase\":\"unsupported\",\"basis\":\"fullodd\",\"point\":"<<row.active<<",\"status\":\""<<odd.diagnostics().status<<"\"}\n";}}
  std::cout<<"{\"phase\":\"summary\",\"selected_rows\":"<<base.rows.size()<<",\"strict_rejected\":"<<strict_rejected<<",\"raw_unsupported\":"<<raw_rejected<<",\"fullodd_unsupported\":"<<odd_rejected<<",\"profiles\":{\"base\":";stats[0].Print();std::cout<<",\"rho_raw\":";stats[1].Print();std::cout<<",\"fullodd_supported_only\":";stats[2].Print();std::cout<<"},\"all_changed_rows_included_for_base_rho\":"<<(stats[0].rows==base.rows.size()&&stats[1].rows==base.rows.size())<<",\"outside_selected_operator_unchanged\":true,\"fullodd_not_complete\":"<<(odd_rejected>0)<<",\"principal_lapse_is_not_complete_RHS\":true,\"production_adopted\":false}\n";
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
